```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean(x):
    if x is None:
        return ""
    return str(x).strip()

def norm(x):
    return clean(x).lower()

def to_number(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        return int(x) if isinstance(x, float) and x.is_integer() else x
    s = clean(x)
    if s:
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except Exception:
            pass
    return x

list1 = {}
for r in range(2, vws.max_row + 1):
    name = vws.cell(row=r, column=7).value
    idv = vws.cell(row=r, column=8).value
    if clean(name) and idv is not None:
        list1[norm(name)] = to_number(idv)

list2 = {}
for r in range(2, vws.max_row + 1):
    name = vws.cell(row=r, column=10).value
    idv = vws.cell(row=r, column=11).value
    if clean(name) and idv is not None:
        list2[norm(name)] = to_number(idv)

results = []
for r in range(2, 8):
    b = vws.cell(row=r, column=2).value
    c = vws.cell(row=r, column=3).value

    b_blank = clean(b) == ""
    c_blank = clean(c) == ""

    if b_blank and c_blank:
        val = None
    else:
        bn = norm(b)
        cn = norm(c)

        if not b_blank and bn in list1:
            val = list1[bn]
        elif not b_blank and cn in list2:
            val = list2[cn]
        elif not b_blank:
            val = 2500
        elif b_blank and cn in list2:
            val = list2[cn]
        else:
            val = 2500

    ws.cell(row=r, column=4).value = val
    results.append(val)

print("list1 size:", len(list1))
print("list2 size:", len(list2))
print("D2:D7:", results)

wb.save(OUT)
